432	    @Override
433	    @Transactional(readOnly = true)
434	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
435	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
436	    }
437	
438	    private <T> T findEntityById(Supplier<T> supplier) {
439	        try {
440	            return supplier.get();
441	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
442	            // Just ignore not found exceptions for Jdbc/Jpa realization
443	            return null;
444	        }
445	    }
446	
447	}
